select 'd4c29b22-ed38-504c-b957-89446eb951f1', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.BIO'), 'qa_passed', 'continuous', '{"title":"Una red alimentaria del manglar","text":"En un manglar del Pacífico colombiano: las hojas del mangle y las algas son comidas por cangrejos y caracoles; los cangrejos son comidos por garzas y por peces pargo; los caracoles son comidos por garzas; los pargos son pescados por las personas. Los hongos y bacterias descomponen los restos de todos los organismos.","svg":null,"table":null}'::jsonb, 'Si los cangrejos aumentan mucho, ¿qué consecuencia podría aparecer después en el manglar?', '[{"label":"A","text":"Ningún efecto, porque las relaciones solo van en una dirección.","is_correct":false,"distractor_type":"Desconoce las relaciones en cadena.","explanation_feedback":"Incorrecta. Los efectos se propagan en la red."},{"label":"B","text":"Más consumo de hojas del mangle, que podría afectar su crecimiento.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Más consumidores primarios presionan más a los productores."},{"label":"C","text":"Menos garzas, porque tendrían más alimento.","is_correct":false,"distractor_type":"Invierte el efecto.","explanation_feedback":"Incorrecta. Más presas suele favorecer a los depredadores."},{"label":"D","text":"Más algas, porque los cangrejos las protegen.","is_correct":false,"distractor_type":"Invierte la relación.","explanation_feedback":"Incorrecta. Los cangrejos comen algas."}]'::jsonb, null, 1.3, 1.3, 0.25, 75, 'original_generated'
