select '924f3198-f119-52e1-84a1-5480dd1c771c', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.BIO'), 'qa_passed', 'continuous', '{"title":"Una red alimentaria del manglar","text":"En un manglar del Pacífico colombiano: las hojas del mangle y las algas son comidas por cangrejos y caracoles; los cangrejos son comidos por garzas y por peces pargo; los caracoles son comidos por garzas; los pargos son pescados por las personas. Los hongos y bacterias descomponen los restos de todos los organismos.","svg":null,"table":null}'::jsonb, '¿Qué papel cumplen los hongos y bacterias en el manglar?', '[{"label":"A","text":"Producen oxígeno por fotosíntesis.","is_correct":false,"distractor_type":"Confunde con productores.","explanation_feedback":"Incorrecta. Los hongos no hacen fotosíntesis."},{"label":"B","text":"Descomponen restos y devuelven nutrientes al ambiente.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Sin descomponedores, los nutrientes quedarían atrapados en los restos."},{"label":"C","text":"Son el alimento principal de los pargos.","is_correct":false,"distractor_type":"Inventa una relación.","explanation_feedback":"Incorrecta. El texto no dice eso."},{"label":"D","text":"Cazan a los cangrejos del manglar.","is_correct":false,"distractor_type":"Confunde con depredadores.","explanation_feedback":"Incorrecta. No son depredadores de cangrejos."}]'::jsonb, null, 1.1, 0, 0.25, 50, 'original_generated'
