select '50ff14e8-8da9-5e96-9b22-26072b784ccb', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.BIO'), 'qa_passed', 'discontinuous', '{"title":"Burbujas de una planta acuática","text":"Unos estudiantes ponen una rama de Elodea, una planta acuática, en un tubo con agua y la iluminan con una lámpara a distintas distancias. Cuentan las burbujas de gas que salen de la planta en un minuto.","svg":null,"table":{"caption":"Burbujas por minuto según la distancia de la lámpara","headers":["Distancia (cm)","Burbujas por minuto"],"rows":[[10,42],[20,25],[30,14],[40,8]]}}'::jsonb, '¿Qué relación muestran los datos?', '[{"label":"A","text":"Solo hay burbujas a 10 cm.","is_correct":false,"distractor_type":"Ignora los otros datos.","explanation_feedback":"Incorrecta. También hay burbujas a 20, 30 y 40 cm."},{"label":"B","text":"La distancia no cambia el número de burbujas.","is_correct":false,"distractor_type":"Ignora los datos.","explanation_feedback":"Incorrecta. Los valores cambian mucho."},{"label":"C","text":"Cuanto más lejos está la lámpara, más burbujas.","is_correct":false,"distractor_type":"Lee al revés la tabla.","explanation_feedback":"Incorrecta. Las burbujas disminuyen con la distancia."},{"label":"D","text":"Cuanto más cerca está la lámpara, más burbujas se producen.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. A 10 cm hay 42 burbujas y a 40 cm, 8."}]'::jsonb, null, 0.9, -1.2, 0.25, 45, 'original_generated'
