select '1d4112e8-2f42-5cb8-8f95-1e778b0a5abe', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.BIO'), 'qa_passed', 'discontinuous', '{"title":"Burbujas de una planta acuática","text":"Unos estudiantes ponen una rama de Elodea, una planta acuática, en un tubo con agua y la iluminan con una lámpara a distintas distancias. Cuentan las burbujas de gas que salen de la planta en un minuto.","svg":null,"table":{"caption":"Burbujas por minuto según la distancia de la lámpara","headers":["Distancia (cm)","Burbujas por minuto"],"rows":[[10,42],[20,25],[30,14],[40,8]]}}'::jsonb, '¿Qué gas forma probablemente las burbujas y por qué?', '[{"label":"A","text":"Nitrógeno, que la planta toma del suelo.","is_correct":false,"distractor_type":"Inventa un proceso.","explanation_feedback":"Incorrecta. La Elodea está en agua y no libera nitrógeno así."},{"label":"B","text":"Oxígeno, que la planta libera al hacer fotosíntesis con la luz.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. En la fotosíntesis la planta usa luz, agua y CO₂ y libera O₂."},{"label":"C","text":"Dióxido de carbono, que la planta produce al hacer fotosíntesis.","is_correct":false,"distractor_type":"Invierte la fotosíntesis.","explanation_feedback":"Incorrecta. El CO₂ se consume en la fotosíntesis."},{"label":"D","text":"Vapor de agua, porque la lámpara hierve el agua.","is_correct":false,"distractor_type":"Atribuye el fenómeno al calor.","explanation_feedback":"Incorrecta. El agua no hierve a esas distancias."}]'::jsonb, null, 1.1, 0, 0.25, 60, 'original_generated'
