select 'da9167d3-c802-54b2-8559-95eee37ef2e9', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.BIO'), 'qa_passed', 'discontinuous', '{"title":"Burbujas de una planta acuática","text":"Unos estudiantes ponen una rama de Elodea, una planta acuática, en un tubo con agua y la iluminan con una lámpara a distintas distancias. Cuentan las burbujas de gas que salen de la planta en un minuto.","svg":null,"table":{"caption":"Burbujas por minuto según la distancia de la lámpara","headers":["Distancia (cm)","Burbujas por minuto"],"rows":[[10,42],[20,25],[30,14],[40,8]]}}'::jsonb, 'Un compañero dice que el aumento de burbujas puede deberse al calor de la lámpara y no a la luz. ¿Cómo podrían comprobarlo?', '[{"label":"A","text":"Apagar la lámpara y contar burbujas a 10 cm.","is_correct":false,"distractor_type":"Elimina la luz y el calor al mismo tiempo.","explanation_feedback":"Incorrecta. No permite distinguir entre las dos causas."},{"label":"B","text":"Usar una planta diferente en cada distancia.","is_correct":false,"distractor_type":"Introduce otra variable.","explanation_feedback":"Incorrecta. Cambiar la planta no separa luz y calor."},{"label":"C","text":"Contar las burbujas durante menos tiempo.","is_correct":false,"distractor_type":"Cambia la medición, no la variable.","explanation_feedback":"Incorrecta. No resuelve la duda sobre la causa."},{"label":"D","text":"Poner entre la lámpara y el tubo un recipiente con agua que absorba el calor y repetir las mediciones.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Así se mantiene la luz y se reduce el calor; si el patrón sigue, la causa es la luz."}]'::jsonb, null, 1.3, 1.3, 0.25, 90, 'original_generated'
