select '6cf1446d-be1e-5777-970b-a817cf550fc1', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.BIO'), 'qa_passed', 'discontinuous', '{"title":"Burbujas de una planta acuática","text":"Unos estudiantes ponen una rama de Elodea, una planta acuática, en un tubo con agua y la iluminan con una lámpara a distintas distancias. Cuentan las burbujas de gas que salen de la planta en un minuto.","svg":null,"table":{"caption":"Burbujas por minuto según la distancia de la lámpara","headers":["Distancia (cm)","Burbujas por minuto"],"rows":[[10,42],[20,25],[30,14],[40,8]]}}'::jsonb, '¿Qué tipo de gráfica representa mejor estos datos?', '[{"label":"A","text":"Una tabla con los nombres de los estudiantes.","is_correct":false,"distractor_type":"Elige datos irrelevantes.","explanation_feedback":"Incorrecta. Los nombres no representan los resultados."},{"label":"B","text":"Una gráfica de puntos o líneas con la distancia en el eje x y las burbujas en el eje y.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Muestra cómo cambia una variable continua al variar la otra."},{"label":"C","text":"Un mapa de la ubicación del laboratorio.","is_correct":false,"distractor_type":"Elige una representación sin relación.","explanation_feedback":"Incorrecta. No muestra la relación entre variables."},{"label":"D","text":"Un diagrama de torta con las cuatro distancias.","is_correct":false,"distractor_type":"Usa un gráfico de partes de un total.","explanation_feedback":"Incorrecta. Las burbujas no son partes de un total."}]'::jsonb, null, 1.1, 0, 0.25, 60, 'original_generated'
