select 'e760f90b-db32-59c1-b221-eefd01e996a8', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.BIO'), 'qa_passed', 'continuous', '{"title":"El color de las semillas","text":"En una planta de arveja, el color amarillo de la semilla (A) domina sobre el verde (a). Se cruzan dos plantas heterocigotas (Aa × Aa).","svg":null,"table":null}'::jsonb, '¿Qué proporción de la descendencia se espera con semillas verdes?', '[{"label":"A","text":"Ninguna (0 %).","is_correct":false,"distractor_type":"Ignora que los padres llevan el alelo a.","explanation_feedback":"Incorrecta. Dos padres Aa pueden tener hijos aa."},{"label":"B","text":"La mitad (50 %).","is_correct":false,"distractor_type":"Cuenta los heterocigotos como verdes.","explanation_feedback":"Incorrecta. Los Aa son amarillos porque A domina."},{"label":"C","text":"Tres cuartos (75 %).","is_correct":false,"distractor_type":"Invierte las proporciones.","explanation_feedback":"Incorrecta. Tres cuartos son amarillos."},{"label":"D","text":"Un cuarto (25 %).","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Solo las plantas aa son verdes; en el cruce Aa × Aa, 1 de cada 4 es aa."}]'::jsonb, null, 1.1, 0, 0.25, 60, 'original_generated'
