select '3ce1f46e-703a-540d-9c0c-67450202b0e0', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.BIO'), 'qa_passed', 'continuous', '{"title":"El color de las semillas","text":"En una planta de arveja, el color amarillo de la semilla (A) domina sobre el verde (a). Se cruzan dos plantas heterocigotas (Aa × Aa).","svg":null,"table":null}'::jsonb, 'Una planta de semillas amarillas puede ser AA o Aa. ¿Qué cruce permite saber cuál es su genotipo?', '[{"label":"A","text":"Cruzarla con una planta verde (aa) y ver si aparece algún descendiente verde.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Si aparece alguna semilla verde, la planta es Aa; si todas son amarillas, probablemente es AA."},{"label":"B","text":"Cruzarla con otra planta amarilla AA.","is_correct":false,"distractor_type":"El cruce no revela el alelo recesivo.","explanation_feedback":"Incorrecta. Con AA todos los hijos son amarillos en ambos casos."},{"label":"C","text":"Medir el tamaño de sus semillas.","is_correct":false,"distractor_type":"Usa un rasgo sin relación.","explanation_feedback":"Incorrecta. El tamaño no indica el genotipo de color."},{"label":"D","text":"Sembrarla en un lugar con más luz.","is_correct":false,"distractor_type":"Confunde ambiente con genética.","explanation_feedback":"Incorrecta. La luz no revela su genotipo."}]'::jsonb, null, 1.3, 1.3, 0.25, 90, 'original_generated'
