select '45b83a9c-18be-5fa1-b7cb-c4355ec1b8fb', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.BIO'), 'qa_passed', 'continuous', '{"title":"El color de las semillas","text":"En una planta de arveja, el color amarillo de la semilla (A) domina sobre el verde (a). Se cruzan dos plantas heterocigotas (Aa × Aa).","svg":null,"table":null}'::jsonb, '¿Qué significa que el amarillo sea dominante?', '[{"label":"A","text":"Que el verde no se hereda.","is_correct":false,"distractor_type":"Desconoce la herencia recesiva.","explanation_feedback":"Incorrecta. El verde sí se hereda como alelo recesivo."},{"label":"B","text":"Que el amarillo es más común en la naturaleza.","is_correct":false,"distractor_type":"Confunde dominancia con frecuencia.","explanation_feedback":"Incorrecta. Dominante no significa más frecuente."},{"label":"C","text":"Que basta un alelo A para que la semilla sea amarilla.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. El rasgo dominante se expresa con una sola copia del alelo."},{"label":"D","text":"Que todas las semillas son amarillas.","is_correct":false,"distractor_type":"Generaliza la dominancia.","explanation_feedback":"Incorrecta. Las plantas aa son verdes."}]'::jsonb, null, 0.9, -1.2, 0.25, 40, 'original_generated'
