select '804643f6-a2de-5c8c-88b6-ae8af05f3243', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.BIO'), 'qa_passed', 'continuous', '{"title":"Mantener el equilibrio","text":"Cuando una persona corre bajo el sol, su temperatura corporal tiende a subir y empieza a sudar. Después de comer, la glucosa en la sangre sube y el páncreas libera insulina, que ayuda a que las células absorban glucosa.","svg":null,"table":null}'::jsonb, '¿Cómo ayuda el sudor a mantener la temperatura corporal?', '[{"label":"A","text":"Al evaporarse de la piel absorbe calor del cuerpo.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. La evaporación requiere energía, que se toma del cuerpo y lo enfría."},{"label":"B","text":"Porque elimina la glucosa de la sangre.","is_correct":false,"distractor_type":"Confunde los dos procesos.","explanation_feedback":"Incorrecta. La glucosa se regula con la insulina."},{"label":"C","text":"Porque aumenta la producción de calor.","is_correct":false,"distractor_type":"Invierte el efecto.","explanation_feedback":"Incorrecta. El sudor sirve para perder calor."},{"label":"D","text":"Porque el sudor es frío cuando sale.","is_correct":false,"distractor_type":"Atribuye el efecto a la temperatura del sudor.","explanation_feedback":"Incorrecta. El enfriamiento ocurre al evaporarse."}]'::jsonb, null, 1.1, 0, 0.25, 60, 'original_generated'
