select 'c6981665-b387-5b83-9bf4-345c2c8991fc', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.BIO'), 'qa_passed', 'continuous', '{"title":"Mantener el equilibrio","text":"Cuando una persona corre bajo el sol, su temperatura corporal tiende a subir y empieza a sudar. Después de comer, la glucosa en la sangre sube y el páncreas libera insulina, que ayuda a que las células absorban glucosa.","svg":null,"table":null}'::jsonb, '¿Qué pasaría con la glucosa en sangre de una persona que no produce suficiente insulina?', '[{"label":"A","text":"Se mantendría alta después de comer.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Sin insulina, las células absorben menos glucosa y esta se acumula en la sangre."},{"label":"B","text":"Bajaría rápidamente a cero.","is_correct":false,"distractor_type":"Invierte el efecto.","explanation_feedback":"Incorrecta. La insulina es la que ayuda a bajarla."},{"label":"C","text":"No cambiaría nunca, comiera o no.","is_correct":false,"distractor_type":"Ignora el efecto de la comida.","explanation_feedback":"Incorrecta. Comer sube la glucosa."},{"label":"D","text":"Se convertiría en sudor.","is_correct":false,"distractor_type":"Mezcla procesos.","explanation_feedback":"Incorrecta. La glucosa no se convierte en sudor."}]'::jsonb, null, 1.1, 0, 0.25, 60, 'original_generated'
