select '66a698c9-93a8-5143-9fa4-fc91414a7ca9', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.BIO'), 'qa_passed', 'continuous', '{"title":"Mantener el equilibrio","text":"Cuando una persona corre bajo el sol, su temperatura corporal tiende a subir y empieza a sudar. Después de comer, la glucosa en la sangre sube y el páncreas libera insulina, que ayuda a que las células absorban glucosa.","svg":null,"table":null}'::jsonb, '¿Qué tienen en común el sudor y la insulina en estos ejemplos?', '[{"label":"A","text":"Ambos son producidos por el páncreas.","is_correct":false,"distractor_type":"Atribuye el sudor al páncreas.","explanation_feedback":"Incorrecta. El sudor lo producen glándulas de la piel."},{"label":"B","text":"Ambos aumentan la temperatura corporal.","is_correct":false,"distractor_type":"Generaliza un efecto que no tienen.","explanation_feedback":"Incorrecta. El sudor la baja y la insulina no la regula."},{"label":"C","text":"Ambos solo ocurren durante el sueño.","is_correct":false,"distractor_type":"Inventa una condición.","explanation_feedback":"Incorrecta. Ocurren en actividad y después de comer."},{"label":"D","text":"Ambos son respuestas que devuelven al cuerpo a un estado estable ante un cambio.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Son ejemplos de homeostasis: el cuerpo corrige un cambio interno."}]'::jsonb, null, 1.3, 1.3, 0.25, 75, 'original_generated'
from public.evidences e where e.code = 'CN.E2.9'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '194c6c89-7d1e-5e48-84da-d8231e78e4e9', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.BIO'), 'qa_passed', 'continuous', '{"title":"Las vacunas","text":"Una vacuna contiene microorganismos debilitados o inactivos, o partes de ellos. Al aplicarla, el sistema inmunitario produce anticuerpos y células de memoria. Si después la persona entra en contacto con el microorganismo real, responde más rápido. Cuando un porcentaje alto de la población está vacunado, el microorganismo circula menos y también se protege a quienes no pueden vacunarse.","svg":null,"table":null}'::jsonb, '¿Qué produce el sistema inmunitario después de aplicar una vacuna?', '[{"label":"A","text":"Antibióticos naturales.","is_correct":false,"distractor_type":"Confunde con medicamentos.","explanation_feedback":"Incorrecta. Los antibióticos son medicamentos externos."},{"label":"B","text":"Anticuerpos y células de memoria.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Es lo que dice el texto."},{"label":"C","text":"Más glóbulos rojos en la sangre.","is_correct":false,"distractor_type":"Confunde con otra función de la sangre.","explanation_feedback":"Incorrecta. Los glóbulos rojos transportan oxígeno."},{"label":"D","text":"Microorganismos nuevos.","is_correct":false,"distractor_type":"Invierte la relación.","explanation_feedback":"Incorrecta. La vacuna no hace que el cuerpo produzca microorganismos."}]'::jsonb, null, 0.9, -1.2, 0.25, 40, 'original_generated'
from public.evidences e where e.code = 'CN.E1.1'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select 'cbdbcd82-c863-5a77-9b76-cba0aa9b7e3d', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.BIO'), 'qa_passed', 'continuous', '{"title":"Las vacunas","text":"Una vacuna contiene microorganismos debilitados o inactivos, o partes de ellos. Al aplicarla, el sistema inmunitario produce anticuerpos y células de memoria. Si después la persona entra en contacto con el microorganismo real, responde más rápido. Cuando un porcentaje alto de la población está vacunado, el microorganismo circula menos y también se protege a quienes no pueden vacunarse.","svg":null,"table":null}'::jsonb, '¿Por qué una persona vacunada responde más rápido ante el microorganismo real?', '[{"label":"A","text":"Porque el microorganismo real es siempre más débil.","is_correct":false,"distractor_type":"Invierte el texto.","explanation_feedback":"Incorrecta. El microorganismo de la vacuna es el debilitado."},{"label":"B","text":"Porque la vacuna mata todos los microorganismos del ambiente.","is_correct":false,"distractor_type":"Exagera el efecto.","explanation_feedback":"Incorrecta. La vacuna actúa en el cuerpo, no en el ambiente."},{"label":"C","text":"Porque las células de memoria lo reconocen y activan la defensa de inmediato.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. La memoria inmunitaria acelera la producción de anticuerpos."},{"label":"D","text":"Porque la vacuna cura la enfermedad ya instalada.","is_correct":false,"distractor_type":"Confunde prevención con tratamiento.","explanation_feedback":"Incorrecta. La vacuna prepara antes del contagio."}]'::jsonb, null, 1.1, 0, 0.25, 60, 'original_generated'
from public.evidences e where e.code = 'CN.E1.1'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '45dd1b54-2baf-5819-9ef6-5e220a947313', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.BIO'), 'qa_passed', 'continuous', '{"title":"Las vacunas","text":"Una vacuna contiene microorganismos debilitados o inactivos, o partes de ellos. Al aplicarla, el sistema inmunitario produce anticuerpos y células de memoria. Si después la persona entra en contacto con el microorganismo real, responde más rápido. Cuando un porcentaje alto de la población está vacunado, el microorganismo circula menos y también se protege a quienes no pueden vacunarse.","svg":null,"table":null}'::jsonb, '¿Por qué la vacunación de muchas personas protege también a un bebé que aún no puede vacunarse?', '[{"label":"A","text":"Porque los bebés nunca se enferman.","is_correct":false,"distractor_type":"Contradice la realidad.","explanation_feedback":"Incorrecta. Los bebés son especialmente vulnerables."},{"label":"B","text":"Porque el microorganismo circula menos y llega menos al bebé.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. La inmunidad colectiva reduce la circulación del microorganismo."},{"label":"C","text":"Porque la vacuna cambia el ADN del bebé.","is_correct":false,"distractor_type":"Inventa un mecanismo.","explanation_feedback":"Incorrecta. Las vacunas no cambian el ADN de otras personas."},{"label":"D","text":"Porque los anticuerpos de los vecinos pasan al bebé por el aire.","is_correct":false,"distractor_type":"Inventa un mecanismo.","explanation_feedback":"Incorrecta. Los anticuerpos no se transmiten por el aire."}]'::jsonb, null, 1.3, 1.3, 0.25, 75, 'original_generated'
from public.evidences e where e.code = 'CN.E1.1'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '7c99f7cd-9f0d-50c9-bd73-5be8355c5c5c', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.BIO'), 'qa_passed', 'continuous', '{"title":"Bacterias resistentes","text":"En una población de bacterias, unas pocas tienen por azar una mutación que las hace resistentes a un antibiótico. Una persona toma el antibiótico solo tres días, en lugar de los siete indicados por el médico, porque ya se siente mejor.","svg":null,"table":null}'::jsonb, '¿Qué efecto puede tener suspender el tratamiento antes de tiempo?', '[{"label":"A","text":"Que el cuerpo produzca más antibiótico.","is_correct":false,"distractor_type":"Inventa un proceso.","explanation_feedback":"Incorrecta. El cuerpo no produce ese antibiótico."},{"label":"B","text":"Que el antibiótico cree bacterias resistentes a propósito.","is_correct":false,"distractor_type":"Malinterpreta el origen de la resistencia.","explanation_feedback":"Incorrecta. La mutación ya existía por azar; el antibiótico la selecciona."},{"label":"C","text":"Que sobrevivan sobre todo las bacterias resistentes y se multipliquen.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. El antibiótico elimina primero a las sensibles; las resistentes quedan y se reproducen."},{"label":"D","text":"Que todas las bacterias se vuelvan sensibles.","is_correct":false,"distractor_type":"Invierte el proceso.","explanation_feedback":"Incorrecta. La selección favorece a las resistentes."}]'::jsonb, null, 1.3, 1.3, 0.25, 90, 'original_generated'
from public.evidences e where e.code = 'CN.E4.5'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '38384d6f-5ed8-5be0-b8cd-605da6d2827c', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.BIO'), 'qa_passed', 'continuous', '{"title":"Bacterias resistentes","text":"En una población de bacterias, unas pocas tienen por azar una mutación que las hace resistentes a un antibiótico. Una persona toma el antibiótico solo tres días, en lugar de los siete indicados por el médico, porque ya se siente mejor.","svg":null,"table":null}'::jsonb, '¿Por qué no se deben usar antibióticos para una gripa causada por un virus?', '[{"label":"A","text":"Porque los antibióticos producen virus.","is_correct":false,"distractor_type":"Inventa un efecto.","explanation_feedback":"Incorrecta. Los antibióticos no producen virus."},{"label":"B","text":"Porque los virus son más grandes que las bacterias.","is_correct":false,"distractor_type":"Invierte los tamaños.","explanation_feedback":"Incorrecta. Los virus suelen ser mucho más pequeños."},{"label":"C","text":"Porque la gripa no es una enfermedad.","is_correct":false,"distractor_type":"Desconoce la gripa como enfermedad.","explanation_feedback":"Incorrecta. La gripa es una infección viral."},{"label":"D","text":"Porque los antibióticos actúan contra bacterias y no contra virus.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Además, su uso innecesario favorece la resistencia bacteriana."}]'::jsonb, null, 1.1, 0, 0.25, 50, 'original_generated'
from public.evidences e where e.code = 'CN.E1.1'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '9a53000f-b437-587c-b852-8828fda9ed18', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.BIO'), 'qa_passed', 'discontinuous', '{"title":"Las partes de la célula","text":null,"svg":null,"table":{"caption":"Algunos organelos y sus funciones","headers":["Organelo","Función"],"rows":[["Núcleo","Contiene el ADN y controla la célula"],["Mitocondria","Obtiene energía de los nutrientes (respiración celular)"],["Cloroplasto","Realiza la fotosíntesis"],["Ribosoma","Fabrica proteínas"],["Membrana celular","Controla qué entra y sale de la célula"]]}}'::jsonb, '¿Qué organelo se encuentra en células vegetales pero no en células animales?', '[{"label":"A","text":"El ribosoma.","is_correct":false,"distractor_type":"Desconoce que ambas lo tienen.","explanation_feedback":"Incorrecta. Ambas tienen ribosomas."},{"label":"B","text":"La mitocondria.","is_correct":false,"distractor_type":"Desconoce que ambas la tienen.","explanation_feedback":"Incorrecta. Plantas y animales tienen mitocondrias."},{"label":"C","text":"El cloroplasto.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Las plantas hacen fotosíntesis en los cloroplastos; los animales no los tienen."},{"label":"D","text":"El núcleo.","is_correct":false,"distractor_type":"Desconoce que ambas lo tienen.","explanation_feedback":"Incorrecta. Las células animales y vegetales tienen núcleo."}]'::jsonb, null, 0.9, -1.2, 0.25, 40, 'original_generated'
from public.evidences e where e.code = 'CN.E5.5'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '32b8fd80-835f-51e0-806c-65be2ea50d44', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.BIO'), 'qa_passed', 'discontinuous', '{"title":"Las partes de la célula","text":null,"svg":null,"table":{"caption":"Algunos organelos y sus funciones","headers":["Organelo","Función"],"rows":[["Núcleo","Contiene el ADN y controla la célula"],["Mitocondria","Obtiene energía de los nutrientes (respiración celular)"],["Cloroplasto","Realiza la fotosíntesis"],["Ribosoma","Fabrica proteínas"],["Membrana celular","Controla qué entra y sale de la célula"]]}}'::jsonb, 'Las células de los músculos tienen muchas mitocondrias. ¿Qué explica esto?', '[{"label":"A","text":"Que hacen fotosíntesis.","is_correct":false,"distractor_type":"Confunde con cloroplastos.","explanation_feedback":"Incorrecta. Los músculos no hacen fotosíntesis."},{"label":"B","text":"Que fabrican mucho ADN.","is_correct":false,"distractor_type":"Confunde con el núcleo.","explanation_feedback":"Incorrecta. El ADN está en el núcleo."},{"label":"C","text":"Que necesitan mucha energía para contraerse.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Las mitocondrias obtienen energía de los nutrientes."},{"label":"D","text":"Que no necesitan energía.","is_correct":false,"distractor_type":"Invierte la relación.","explanation_feedback":"Incorrecta. Tener muchas mitocondrias indica alta demanda de energía."}]'::jsonb, null, 1.1, 0, 0.25, 50, 'original_generated'
from public.evidences e where e.code = 'CN.E5.5'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select 'c2e696f0-9d8e-5499-9b06-c1fc68abe041', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.BIO'), 'qa_passed', 'discontinuous', '{"title":"Las partes de la célula","text":null,"svg":null,"table":{"caption":"Algunos organelos y sus funciones","headers":["Organelo","Función"],"rows":[["Núcleo","Contiene el ADN y controla la célula"],["Mitocondria","Obtiene energía de los nutrientes (respiración celular)"],["Cloroplasto","Realiza la fotosíntesis"],["Ribosoma","Fabrica proteínas"],["Membrana celular","Controla qué entra y sale de la célula"]]}}'::jsonb, 'Un veneno bloquea las mitocondrias. ¿Qué le pasaría a la célula?', '[{"label":"A","text":"Fabricaría más proteínas.","is_correct":false,"distractor_type":"Inventa un efecto.","explanation_feedback":"Incorrecta. Sin energía, más bien fabricaría menos."},{"label":"B","text":"Empezaría a hacer fotosíntesis.","is_correct":false,"distractor_type":"Inventa una compensación.","explanation_feedback":"Incorrecta. Una célula animal no puede hacer fotosíntesis."},{"label":"C","text":"Se quedaría sin energía y podría morir.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Sin respiración celular, la célula no obtiene energía de los nutrientes."},{"label":"D","text":"Dejaría de tener ADN en el núcleo.","is_correct":false,"distractor_type":"Confunde con el núcleo.","explanation_feedback":"Incorrecta. Bloquear mitocondrias no elimina el ADN nuclear."}]'::jsonb, null, 1.3, 1.3, 0.25, 75, 'original_generated'
from public.evidences e where e.code = 'CN.E2.9'
on conflict (id) do nothing;
