select '172d1d99-4991-513c-b53e-6deec0b6adb1', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.BIO'), 'qa_passed', 'continuous', '{"title":"El pez león en el Caribe","text":"El pez león, originario del océano Índico y Pacífico, llegó al Caribe, probablemente liberado de acuarios. En los arrecifes colombianos se come peces pequeños nativos y no tiene depredadores naturales que lo controlen. Algunas comunidades de pescadores lo capturan y lo venden para consumo.","svg":null,"table":null}'::jsonb, '¿Por qué el pez león se ha multiplicado tanto en el Caribe?', '[{"label":"A","text":"Porque es nativo de los arrecifes colombianos.","is_correct":false,"distractor_type":"Contradice el texto.","explanation_feedback":"Incorrecta. Es originario del Índico y el Pacífico."},{"label":"B","text":"Porque los pescadores lo protegen.","is_correct":false,"distractor_type":"Contradice el texto.","explanation_feedback":"Incorrecta. Los pescadores lo capturan."},{"label":"C","text":"Porque se alimenta de algas que abundan en el Caribe.","is_correct":false,"distractor_type":"Inventa su dieta.","explanation_feedback":"Incorrecta. El texto dice que come peces pequeños."},{"label":"D","text":"Porque no tiene depredadores naturales que controlen su población.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Sin depredadores, su población crece sin freno."}]'::jsonb, null, 1.1, 0, 0.25, 60, 'original_generated'
from public.evidences e where e.code = 'CN.E2.8'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select 'a5a38eda-ac2d-5b49-a974-21c8c871037c', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.BIO'), 'qa_passed', 'continuous', '{"title":"El pez león en el Caribe","text":"El pez león, originario del océano Índico y Pacífico, llegó al Caribe, probablemente liberado de acuarios. En los arrecifes colombianos se come peces pequeños nativos y no tiene depredadores naturales que lo controlen. Algunas comunidades de pescadores lo capturan y lo venden para consumo.","svg":null,"table":null}'::jsonb, '¿Qué efecto puede tener el pez león en los arrecifes a largo plazo?', '[{"label":"A","text":"Disminuir las poblaciones de peces nativos y alterar el equilibrio del arrecife.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Al comerse a los peces nativos, cambia la red alimentaria del arrecife."},{"label":"B","text":"Desaparecer por sí solo en pocos meses.","is_correct":false,"distractor_type":"Ignora que no tiene depredadores.","explanation_feedback":"Incorrecta. Sin depredadores, no hay razón para que desaparezca."},{"label":"C","text":"Mejorar la calidad del agua del arrecife.","is_correct":false,"distractor_type":"Inventa un efecto.","explanation_feedback":"Incorrecta. El texto no lo sugiere."},{"label":"D","text":"Aumentar la diversidad de peces nativos.","is_correct":false,"distractor_type":"Invierte el efecto.","explanation_feedback":"Incorrecta. Se come a los nativos."}]'::jsonb, null, 1.3, 1.3, 0.25, 75, 'original_generated'
from public.evidences e where e.code = 'CN.E5.7'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '25a3761e-2aa1-5eb0-91a6-1b572becd56d', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.BIO'), 'qa_passed', 'continuous', '{"title":"El pez león en el Caribe","text":"El pez león, originario del océano Índico y Pacífico, llegó al Caribe, probablemente liberado de acuarios. En los arrecifes colombianos se come peces pequeños nativos y no tiene depredadores naturales que lo controlen. Algunas comunidades de pescadores lo capturan y lo venden para consumo.","svg":null,"table":null}'::jsonb, '¿Qué beneficio tiene que las comunidades pesquen y vendan pez león?', '[{"label":"A","text":"Ayuda a controlar su población y genera ingresos para los pescadores.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Une un beneficio ambiental con uno económico."},{"label":"B","text":"Protege a sus depredadores naturales.","is_correct":false,"distractor_type":"Contradice el texto.","explanation_feedback":"Incorrecta. En el Caribe no tiene depredadores naturales."},{"label":"C","text":"Introduce el pez en nuevos océanos.","is_correct":false,"distractor_type":"Confunde la pesca con la liberación.","explanation_feedback":"Incorrecta. Pescarlo no lo lleva a otros océanos."},{"label":"D","text":"Aumenta su población en los arrecifes.","is_correct":false,"distractor_type":"Invierte el efecto.","explanation_feedback":"Incorrecta. La pesca la reduce."}]'::jsonb, null, 1.1, 0, 0.25, 50, 'original_generated'
from public.evidences e where e.code = 'CN.E1.2'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '82dc32a2-c2f2-531a-8ab6-9bfd3c72c769', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.BIO'), 'qa_passed', 'continuous', '{"title":"Criaderos de zancudos","text":"El zancudo Aedes aegypti transmite el dengue. Sus larvas se desarrollan en agua quieta acumulada, por ejemplo en llantas, tarros, floreros y tanques destapados.","svg":null,"table":null}'::jsonb, '¿Qué medida ayuda a prevenir el dengue en una casa?', '[{"label":"A","text":"Tapar los tanques y no dejar agua quieta en recipientes.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Elimina los lugares donde se desarrollan las larvas."},{"label":"B","text":"Guardar llantas viejas en el patio.","is_correct":false,"distractor_type":"Favorece criaderos.","explanation_feedback":"Incorrecta. Las llantas acumulan agua de lluvia."},{"label":"C","text":"Regar más las plantas del jardín.","is_correct":false,"distractor_type":"Puede aumentar el agua acumulada.","explanation_feedback":"Incorrecta. Más agua estancada favorece al zancudo."},{"label":"D","text":"Tomar antibióticos cada semana.","is_correct":false,"distractor_type":"Confunde virus con bacterias.","explanation_feedback":"Incorrecta. El dengue lo causa un virus y no se previene con antibióticos."}]'::jsonb, null, 0.9, -1.2, 0.25, 40, 'original_generated'
from public.evidences e where e.code = 'CN.E1.1'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select 'fa56e7a9-d030-5c62-825a-33058c9fcd71', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.BIO'), 'qa_passed', 'continuous', '{"title":"Criaderos de zancudos","text":"El zancudo Aedes aegypti transmite el dengue. Sus larvas se desarrollan en agua quieta acumulada, por ejemplo en llantas, tarros, floreros y tanques destapados.","svg":null,"table":null}'::jsonb, '¿Por qué los casos de dengue suelen aumentar en temporadas de lluvia?', '[{"label":"A","text":"Porque los zancudos mueren con el agua.","is_correct":false,"distractor_type":"Invierte el efecto.","explanation_feedback":"Incorrecta. El agua quieta favorece su reproducción."},{"label":"B","text":"Porque las personas se bañan más.","is_correct":false,"distractor_type":"Inventa una causa.","explanation_feedback":"Incorrecta. Bañarse no transmite dengue."},{"label":"C","text":"Porque la lluvia transmite el virus.","is_correct":false,"distractor_type":"Inventa una vía de contagio.","explanation_feedback":"Incorrecta. El virus lo transmite el zancudo."},{"label":"D","text":"Porque hay más recipientes con agua acumulada donde se crían los zancudos.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. La lluvia llena tarros y llantas que se vuelven criaderos."}]'::jsonb, null, 1.1, 0, 0.25, 50, 'original_generated'
from public.evidences e where e.code = 'CN.E2.8'
