insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '0d8a0b6f-8aa6-5026-9208-c8ddcf1d5d1e', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.BIO'), 'qa_passed', 'discontinuous', '{"title":"Enzimas y temperatura","text":"Una enzima de la saliva, la amilasa, descompone el almidón. Unos estudiantes mezclan almidón con amilasa a diferentes temperaturas y miden cuánto tarda en descomponerse.","svg":null,"table":{"caption":"Tiempo de descomposición del almidón según la temperatura","headers":["Temperatura (°C)","Tiempo (minutos)"],"rows":[[10,18],[25,9],[37,4],[50,11],[70,"No se descompuso"]]}}'::jsonb, '¿A qué temperatura funciona mejor la amilasa según los datos?', '[{"label":"A","text":"A 10 °C.","is_correct":false,"distractor_type":"Interpreta al revés el tiempo.","explanation_feedback":"Incorrecta. A 10 °C tardó 18 minutos, el mayor tiempo medido con resultado."},{"label":"B","text":"Cerca de 37 °C.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. A 37 °C el almidón se descompuso más rápido: 4 minutos."},{"label":"C","text":"A 50 °C.","is_correct":false,"distractor_type":"No compara todos los valores.","explanation_feedback":"Incorrecta. A 50 °C tardó 11 minutos, más que a 37 °C."},{"label":"D","text":"A 70 °C.","is_correct":false,"distractor_type":"Supone que más calor siempre acelera.","explanation_feedback":"Incorrecta. A 70 °C el almidón no se descompuso."}]'::jsonb, null, 1.1, 0, 0.25, 50, 'original_generated'
