select 'c3990f38-bd40-574e-94b0-8fc67e1727af', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.BIO'), 'qa_passed', 'discontinuous', '{"title":"Enzimas y temperatura","text":"Una enzima de la saliva, la amilasa, descompone el almidón. Unos estudiantes mezclan almidón con amilasa a diferentes temperaturas y miden cuánto tarda en descomponerse.","svg":null,"table":{"caption":"Tiempo de descomposición del almidón según la temperatura","headers":["Temperatura (°C)","Tiempo (minutos)"],"rows":[[10,18],[25,9],[37,4],[50,11],[70,"No se descompuso"]]}}'::jsonb, '¿Qué explica que a 70 °C el almidón no se descomponga?', '[{"label":"A","text":"La enzima funciona mejor cuanto más calor hay.","is_correct":false,"distractor_type":"Contradice los datos.","explanation_feedback":"Incorrecta. A 50 °C ya funciona peor que a 37 °C."},{"label":"B","text":"El calor alteró la estructura de la enzima y dejó de funcionar.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Las enzimas son proteínas que se desnaturalizan con temperaturas altas."},{"label":"C","text":"El almidón se evapora a 70 °C.","is_correct":false,"distractor_type":"Inventa un cambio de fase.","explanation_feedback":"Incorrecta. El almidón no se evapora a esa temperatura."},{"label":"D","text":"A 70 °C el almidón se convierte en enzima.","is_correct":false,"distractor_type":"Inventa un proceso.","explanation_feedback":"Incorrecta. El almidón no se convierte en enzima."}]'::jsonb, null, 1.3, 1.3, 0.25, 75, 'original_generated'
