select 'cd43c68a-3246-5b62-96bf-4bc6b027ffed', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.BIO'), 'qa_passed', 'discontinuous', '{"title":"Enzimas y temperatura","text":"Una enzima de la saliva, la amilasa, descompone el almidón. Unos estudiantes mezclan almidón con amilasa a diferentes temperaturas y miden cuánto tarda en descomponerse.","svg":null,"table":{"caption":"Tiempo de descomposición del almidón según la temperatura","headers":["Temperatura (°C)","Tiempo (minutos)"],"rows":[[10,18],[25,9],[37,4],[50,11],[70,"No se descompuso"]]}}'::jsonb, '¿Por qué es esperable que la amilasa humana funcione mejor cerca de 37 °C?', '[{"label":"A","text":"Porque las enzimas no dependen de la temperatura.","is_correct":false,"distractor_type":"Contradice los datos.","explanation_feedback":"Incorrecta. Los datos muestran que sí dependen."},{"label":"B","text":"Porque a 37 °C el almidón es más dulce.","is_correct":false,"distractor_type":"Atribuye el efecto al sabor.","explanation_feedback":"Incorrecta. El sabor no explica la actividad enzimática."},{"label":"C","text":"Porque esa es la temperatura normal del cuerpo humano.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Las enzimas humanas suelen funcionar mejor a la temperatura corporal."},{"label":"D","text":"Porque a 37 °C hierve el agua.","is_correct":false,"distractor_type":"Confunde temperaturas.","explanation_feedback":"Incorrecta. El agua hierve a 100 °C."}]'::jsonb, null, 1.1, 0, 0.25, 50, 'original_generated'
