select '82743c69-e169-5d8d-9feb-beae7e471af3', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.BIO'), 'qa_passed', 'discontinuous', '{"title":"El corazón durante el ejercicio","text":null,"svg":null,"table":{"caption":"Frecuencia cardiaca de una estudiante (pulsaciones por minuto)","headers":["Momento","Pulsaciones por minuto"],"rows":[["En reposo",70],["Tras 5 min de trote",120],["Tras 10 min de trote",145],["5 min después de parar",90]]}}'::jsonb, '¿Por qué aumenta la frecuencia cardiaca durante el ejercicio?', '[{"label":"A","text":"Porque el corazón se cansa y late sin control.","is_correct":false,"distractor_type":"Interpreta la respuesta como falla.","explanation_feedback":"Incorrecta. Es una respuesta normal y regulada."},{"label":"B","text":"Porque los músculos necesitan más oxígeno y nutrientes, y el corazón bombea más sangre.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. El sistema circulatorio responde a la mayor demanda de los músculos."},{"label":"C","text":"Porque los pulmones dejan de funcionar.","is_correct":false,"distractor_type":"Inventa una causa.","explanation_feedback":"Incorrecta. Los pulmones también trabajan más."},{"label":"D","text":"Porque baja la temperatura del cuerpo.","is_correct":false,"distractor_type":"Invierte el efecto.","explanation_feedback":"Incorrecta. La temperatura suele subir al hacer ejercicio."}]'::jsonb, null, 1.1, 0, 0.25, 60, 'original_generated'
