select '187cc700-2bc7-5f38-9fd2-bfa8dd6967ab', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.BIO'), 'qa_passed', 'discontinuous', '{"title":"El corazón durante el ejercicio","text":null,"svg":null,"table":{"caption":"Frecuencia cardiaca de una estudiante (pulsaciones por minuto)","headers":["Momento","Pulsaciones por minuto"],"rows":[["En reposo",70],["Tras 5 min de trote",120],["Tras 10 min de trote",145],["5 min después de parar",90]]}}'::jsonb, 'Si la estudiante sigue descansando 10 minutos más, ¿qué valor es más probable?', '[{"label":"A","text":"Uno mayor que 145.","is_correct":false,"distractor_type":"Ignora la tendencia a bajar.","explanation_feedback":"Incorrecta. En reposo la frecuencia disminuye."},{"label":"B","text":"Exactamente 120.","is_correct":false,"distractor_type":"Repite un valor de ejercicio.","explanation_feedback":"Incorrecta. En reposo debería bajar de 90."},{"label":"C","text":"Uno cercano a 70 pulsaciones por minuto.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. La frecuencia tiende a volver al valor de reposo."},{"label":"D","text":"Cero pulsaciones.","is_correct":false,"distractor_type":"Exagera la bajada.","explanation_feedback":"Incorrecta. El corazón no se detiene al descansar."}]'::jsonb, null, 1.1, 0, 0.25, 50, 'original_generated'
