select '9ecd5d24-ddca-52d8-bc00-dd473281364b', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.BIO'), 'qa_passed', 'continuous', '{"title":"Cromosomas y reproducción","text":"Las células del cuerpo humano tienen 46 cromosomas. Los óvulos y los espermatozoides se forman por meiosis y tienen la mitad. En la fecundación, un óvulo y un espermatozoide se unen y forman la primera célula de un nuevo individuo.","svg":null,"table":null}'::jsonb, '¿Cuántos cromosomas tiene un espermatozoide humano?', '[{"label":"A","text":"23.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. La meiosis reduce a la mitad el número de cromosomas: 46 / 2 = 23."},{"label":"B","text":"92.","is_correct":false,"distractor_type":"Duplica en lugar de dividir.","explanation_feedback":"Incorrecta. Ninguna célula normal tiene 92 cromosomas."},{"label":"C","text":"12.","is_correct":false,"distractor_type":"Divide de más.","explanation_feedback":"Incorrecta. La meiosis divide entre dos, no entre cuatro."},{"label":"D","text":"46.","is_correct":false,"distractor_type":"Olvida la reducción por meiosis.","explanation_feedback":"Incorrecta. Las células sexuales tienen la mitad."}]'::jsonb, null, 1.1, 0, 0.25, 45, 'original_generated'
