select 'e554adfd-922c-5cb6-9770-4e00a9799e0a', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.BIO'), 'qa_passed', 'continuous', '{"title":"Cromosomas y reproducción","text":"Las células del cuerpo humano tienen 46 cromosomas. Los óvulos y los espermatozoides se forman por meiosis y tienen la mitad. En la fecundación, un óvulo y un espermatozoide se unen y forman la primera célula de un nuevo individuo.","svg":null,"table":null}'::jsonb, '¿Por qué es importante que las células sexuales tengan la mitad de los cromosomas?', '[{"label":"A","text":"Para que los hijos tengan el doble de cromosomas que los padres.","is_correct":false,"distractor_type":"Invierte el efecto.","explanation_feedback":"Incorrecta. El número se mantiene."},{"label":"B","text":"Para que solo uno de los padres aporte información genética.","is_correct":false,"distractor_type":"Contradice la fecundación.","explanation_feedback":"Incorrecta. Ambos padres aportan cromosomas."},{"label":"C","text":"Para que al unirse en la fecundación se recupere el número normal de 46.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. 23 + 23 = 46: el número se mantiene entre generaciones."},{"label":"D","text":"Para que las células sexuales sean más rápidas.","is_correct":false,"distractor_type":"Inventa una razón.","explanation_feedback":"Incorrecta. La razón es genética."}]'::jsonb, null, 1.3, 1.3, 0.25, 60, 'original_generated'
