select '6b757aea-39d4-598e-b951-83504dfb3938', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.BIO'), 'qa_passed', 'continuous', '{"title":"Cromosomas y reproducción","text":"Las células del cuerpo humano tienen 46 cromosomas. Los óvulos y los espermatozoides se forman por meiosis y tienen la mitad. En la fecundación, un óvulo y un espermatozoide se unen y forman la primera célula de un nuevo individuo.","svg":null,"table":null}'::jsonb, '¿Qué diferencia la reproducción sexual de la asexual?', '[{"label":"A","text":"Solo los animales se reproducen de forma sexual.","is_correct":false,"distractor_type":"Generaliza mal.","explanation_feedback":"Incorrecta. Muchas plantas también lo hacen."},{"label":"B","text":"La sexual produce copias idénticas del progenitor.","is_correct":false,"distractor_type":"Invierte la definición.","explanation_feedback":"Incorrecta. Eso ocurre en la asexual."},{"label":"C","text":"En la asexual siempre participan dos progenitores.","is_correct":false,"distractor_type":"Invierte la definición.","explanation_feedback":"Incorrecta. La asexual tiene un solo progenitor."},{"label":"D","text":"En la sexual se combina información genética de dos progenitores.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Por eso produce más variedad que la asexual."}]'::jsonb, null, 1.1, 0, 0.25, 50, 'original_generated'
