select 'abc02a5f-520d-5d86-80bb-5a30c71fde0b', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.BIO'), 'qa_passed', 'continuous', '{"title":"Escarabajos de dos colores","text":"En un bosque viven escarabajos verdes y cafés de la misma especie. Las aves los ven y se los comen con más facilidad cuando su color contrasta con el de los troncos. Después de un incendio, la mayoría de los troncos quedaron oscuros por varios años.","svg":null,"table":null}'::jsonb, '¿Qué cambio se espera en la población de escarabajos en los años siguientes al incendio?', '[{"label":"A","text":"Que no cambie la proporción.","is_correct":false,"distractor_type":"Ignora la presión de las aves.","explanation_feedback":"Incorrecta. Las aves comen más a los que contrastan."},{"label":"B","text":"Que todos se vuelvan cafés porque quieren esconderse.","is_correct":false,"distractor_type":"Atribuye intención al cambio.","explanation_feedback":"Incorrecta. No cambian por voluntad; es selección natural."},{"label":"C","text":"Que aumente la proporción de escarabajos cafés.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Los cafés se confunden mejor con los troncos oscuros, sobreviven más y dejan más descendientes."},{"label":"D","text":"Que aumente la proporción de verdes.","is_correct":false,"distractor_type":"Ignora el contraste.","explanation_feedback":"Incorrecta. Los verdes resaltan sobre troncos oscuros."}]'::jsonb, null, 1.3, 1.3, 0.25, 75, 'original_generated'
