select '5c376b81-f27b-50f1-b2a1-976be0645dd9', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.BIO'), 'qa_passed', 'continuous', '{"title":"Escarabajos de dos colores","text":"En un bosque viven escarabajos verdes y cafés de la misma especie. Las aves los ven y se los comen con más facilidad cuando su color contrasta con el de los troncos. Después de un incendio, la mayoría de los troncos quedaron oscuros por varios años.","svg":null,"table":null}'::jsonb, '¿Qué modelo biológico explica mejor este cambio?', '[{"label":"A","text":"La generación espontánea.","is_correct":false,"distractor_type":"Usa una idea descartada.","explanation_feedback":"Incorrecta. Los escarabajos nacen de otros escarabajos."},{"label":"B","text":"La herencia de caracteres adquiridos.","is_correct":false,"distractor_type":"Usa una idea descartada.","explanation_feedback":"Incorrecta. Un escarabajo no cambia de color por el ambiente y lo hereda."},{"label":"C","text":"La selección natural.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Los individuos con rasgos ventajosos sobreviven y se reproducen más."},{"label":"D","text":"La fotosíntesis.","is_correct":false,"distractor_type":"Elige un proceso sin relación.","explanation_feedback":"Incorrecta. Los escarabajos no hacen fotosíntesis."}]'::jsonb, null, 1.3, 1.3, 0.25, 50, 'original_generated'
