select '4176dca1-9868-55fa-90ee-edcedc6c9bd5', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.BIO'), 'qa_passed', 'continuous', '{"title":"Fotosíntesis y respiración","text":"Fotosíntesis: dióxido de carbono + agua + luz → glucosa + oxígeno.\nRespiración celular: glucosa + oxígeno → dióxido de carbono + agua + energía.","svg":null,"table":null}'::jsonb, '¿Qué relación hay entre los dos procesos?', '[{"label":"A","text":"Los dos necesitan luz.","is_correct":false,"distractor_type":"Generaliza la fotosíntesis.","explanation_feedback":"Incorrecta. La respiración no necesita luz."},{"label":"B","text":"Los productos de uno son los reactivos del otro.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. El oxígeno y la glucosa de la fotosíntesis se usan en la respiración, y viceversa."},{"label":"C","text":"Los dos producen oxígeno.","is_correct":false,"distractor_type":"Lee mal la respiración.","explanation_feedback":"Incorrecta. La respiración consume oxígeno."},{"label":"D","text":"Los dos procesos solo ocurren en animales.","is_correct":false,"distractor_type":"Desconoce dónde ocurren.","explanation_feedback":"Incorrecta. Las plantas hacen ambos."}]'::jsonb, null, 1.1, 0, 0.25, 60, 'original_generated'
