select 'f1c3e22d-3ccb-581d-9030-bd88b60402f1', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.BIO'), 'qa_passed', 'continuous', '{"title":"Fotosíntesis y respiración","text":"Fotosíntesis: dióxido de carbono + agua + luz → glucosa + oxígeno.\nRespiración celular: glucosa + oxígeno → dióxido de carbono + agua + energía.","svg":null,"table":null}'::jsonb, '¿Las plantas respiran?', '[{"label":"A","text":"Sí, de día y de noche, como todos los seres vivos.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Las plantas obtienen energía con la respiración celular todo el tiempo; de día también hacen fotosíntesis."},{"label":"B","text":"No, las plantas solo hacen fotosíntesis.","is_correct":false,"distractor_type":"Confunde los procesos.","explanation_feedback":"Incorrecta. Las plantas también necesitan energía de la respiración."},{"label":"C","text":"Solo de noche, cuando no hay fotosíntesis.","is_correct":false,"distractor_type":"Supone que se alternan.","explanation_feedback":"Incorrecta. Respiran también de día."},{"label":"D","text":"Solo de día, cuando hay luz.","is_correct":false,"distractor_type":"Asocia la respiración con la luz.","explanation_feedback":"Incorrecta. La respiración no depende de la luz."}]'::jsonb, null, 1.3, 1.3, 0.25, 60, 'original_generated'
