select 'f9e2782b-62be-56b6-a21f-83232a6a9be0', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.BIO'), 'qa_passed', 'continuous', '{"title":"Semillas que germinan","text":"Una estudiante pone 20 semillas de fríjol en cada uno de cuatro vasos con algodón. Vaso 1: algodón húmedo, luz y 25 °C. Vaso 2: algodón seco, luz y 25 °C. Vaso 3: algodón húmedo, oscuridad y 25 °C. Vaso 4: algodón húmedo, luz y 5 °C. Después de una semana germinaron: 18, 0, 17 y 2.","svg":null,"table":null}'::jsonb, '¿Qué conclusión apoyan los resultados?', '[{"label":"A","text":"Necesitan agua y temperatura adecuada, pero no luz.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Sin agua no germinaron, con frío casi no, y en oscuridad sí."},{"label":"B","text":"Las semillas necesitan luz para germinar.","is_correct":false,"distractor_type":"Ignora el vaso 3.","explanation_feedback":"Incorrecta. En oscuridad germinaron 17."},{"label":"C","text":"El agua impide que germinen.","is_correct":false,"distractor_type":"Invierte el efecto del agua.","explanation_feedback":"Incorrecta. Sin agua no germinó ninguna."},{"label":"D","text":"La temperatura no afecta la germinación.","is_correct":false,"distractor_type":"Ignora el vaso 4.","explanation_feedback":"Incorrecta. A 5 °C germinaron solo 2."}]'::jsonb, null, 1.1, 0, 0.25, 75, 'original_generated'
