select '8703a629-9673-55bd-aecc-48f492f89ffd', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.BIO'), 'qa_passed', 'continuous', '{"title":"Semillas que germinan","text":"Una estudiante pone 20 semillas de fríjol en cada uno de cuatro vasos con algodón. Vaso 1: algodón húmedo, luz y 25 °C. Vaso 2: algodón seco, luz y 25 °C. Vaso 3: algodón húmedo, oscuridad y 25 °C. Vaso 4: algodón húmedo, luz y 5 °C. Después de una semana germinaron: 18, 0, 17 y 2.","svg":null,"table":null}'::jsonb, '¿Por qué la estudiante usó 20 semillas por vaso y no una?', '[{"label":"A","text":"Porque una semilla sola nunca germina.","is_correct":false,"distractor_type":"Inventa una regla.","explanation_feedback":"Incorrecta. Una semilla puede germinar sola."},{"label":"B","text":"Para no depender de una sola semilla que podría estar dañada.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Muchas semillas reducen el efecto de casos individuales."},{"label":"C","text":"Para gastar todas las semillas del paquete.","is_correct":false,"distractor_type":"Da una razón práctica sin valor científico.","explanation_feedback":"Incorrecta. La razón es la confiabilidad."},{"label":"D","text":"Para que las semillas crezcan más rápido.","is_correct":false,"distractor_type":"Confunde la cantidad con la rapidez.","explanation_feedback":"Incorrecta. El número no acelera la germinación."}]'::jsonb, null, 1.1, 0, 0.25, 50, 'original_generated'
