select 'fd442051-d243-5fe7-91d1-29572512bced', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.BIO'), 'qa_passed', 'continuous', '{"title":"Semillas que germinan","text":"Una estudiante pone 20 semillas de fríjol en cada uno de cuatro vasos con algodón. Vaso 1: algodón húmedo, luz y 25 °C. Vaso 2: algodón seco, luz y 25 °C. Vaso 3: algodón húmedo, oscuridad y 25 °C. Vaso 4: algodón húmedo, luz y 5 °C. Después de una semana germinaron: 18, 0, 17 y 2.","svg":null,"table":null}'::jsonb, '¿Qué pregunta NO se puede responder con este experimento?', '[{"label":"A","text":"¿Qué tipo de suelo produce plantas de fríjol más altas?","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. No se usó suelo ni se midió la altura de las plantas."},{"label":"B","text":"¿Influye la temperatura en la germinación del fríjol?","is_correct":false,"distractor_type":"Esa sí se responde (vasos 1 y 4).","explanation_feedback":"Incorrecta. Compara 25 °C y 5 °C."},{"label":"C","text":"¿Necesitan agua las semillas de fríjol para germinar?","is_correct":false,"distractor_type":"Esa sí se responde (vasos 1 y 2).","explanation_feedback":"Incorrecta. Compara húmedo y seco."},{"label":"D","text":"¿Influye la luz en la germinación del fríjol?","is_correct":false,"distractor_type":"Esa sí se responde (vasos 1 y 3).","explanation_feedback":"Incorrecta. Compara luz y oscuridad."}]'::jsonb, null, 1.3, 1.3, 0.25, 75, 'original_generated'
