select '02e4e33d-ae7e-5204-96e9-223cb07bc118', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.BIO'), 'qa_passed', 'continuous', '{"title":"Después del incendio","text":"Tras un incendio en un bosque andino, primero aparecen hierbas y helechos. Años después crecen arbustos, y décadas más tarde, árboles que dan sombra y hacen que algunas de las primeras hierbas desaparezcan.","svg":null,"table":null}'::jsonb, '¿Cómo se llama el proceso descrito?', '[{"label":"A","text":"Migración.","is_correct":false,"distractor_type":"Elige un movimiento de animales.","explanation_feedback":"Incorrecta. El texto describe cambios de vegetación en el mismo lugar."},{"label":"B","text":"Fotosíntesis.","is_correct":false,"distractor_type":"Elige un proceso celular.","explanation_feedback":"Incorrecta. La fotosíntesis ocurre en cada planta, no describe el cambio de comunidades."},{"label":"C","text":"Sucesión ecológica.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Es el reemplazo gradual de comunidades después de una perturbación."},{"label":"D","text":"Mutación.","is_correct":false,"distractor_type":"Elige un proceso genético.","explanation_feedback":"Incorrecta. No se trata de cambios en el ADN."}]'::jsonb, null, 1.1, 0, 0.25, 45, 'original_generated'
