select '9674a3f8-ebb0-52af-8673-0bfcec26ed61', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.BIO'), 'qa_passed', 'continuous', '{"title":"Después del incendio","text":"Tras un incendio en un bosque andino, primero aparecen hierbas y helechos. Años después crecen arbustos, y décadas más tarde, árboles que dan sombra y hacen que algunas de las primeras hierbas desaparezcan.","svg":null,"table":null}'::jsonb, '¿Por qué desaparecen algunas hierbas cuando crecen los árboles?', '[{"label":"A","text":"Porque las hierbas se convierten en árboles.","is_correct":false,"distractor_type":"Inventa una transformación.","explanation_feedback":"Incorrecta. Son especies distintas."},{"label":"B","text":"Porque el incendio vuelve a ocurrir.","is_correct":false,"distractor_type":"Inventa un evento.","explanation_feedback":"Incorrecta. El texto no menciona otro incendio."},{"label":"C","text":"Porque los árboles se comen las hierbas.","is_correct":false,"distractor_type":"Atribuye alimentación a los árboles.","explanation_feedback":"Incorrecta. Los árboles no se comen otras plantas."},{"label":"D","text":"Porque la sombra de los árboles reduce la luz que necesitan.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Los árboles compiten por la luz y cambian las condiciones del lugar."}]'::jsonb, null, 1.3, 1.3, 0.25, 60, 'original_generated'
